$ProjectDir = "C:\ollama\cvn_node"; $BackupDir = "C:\ollama\cvn_node\backups"; if (!(Test-Path -Path $BackupDir)) { New-Item -ItemType Directory -Path $BackupDir | Out-Null }; Write-Host "--- INITIALIZING IMMUTABLE BACKGROUND BINARY DATABASE BACKUP LOOP ---" -ForegroundColor Cyan; while ($true) { if (Test-Path -Path "$ProjectDir\cvn_mainnet.db") { $Timestamp = Get-Date -Format "yyMMdd_HHmmss"; Copy-Item -Path "$ProjectDir\cvn_mainnet.db" -Destination "$BackupDir\cvn_mainnet_backup_$Timestamp.db" -Force; Write-Host "🟩 SUCCESS: Fork-proof timestamped binary database backup written cleanly!" -ForegroundColor Green } else { Write-Host "⚠️ WARNING: Live cvn_mainnet.db database file not found in main directory path." -ForegroundColor Yellow }; Start-Sleep -Seconds 86400 }